class ReplaceConfirmationDialog(object):
def __init__(self, main_window): self.main_window = main_window self.search_context = None self.replacement = None
def run(self, original, replacement, number_of_occurrences, search_context): self.search_context = search_context self.replacement = replacement self.setup(original, replacement, number_of_occurrences) self.view.choose(self.main_window, None, self.dialog_process_response)
def setup(self, original, replacement, number_of_occurrences): self.view = Gtk.AlertDialog() self.view.set_modal(True) str_occurrences = ngettext('Replacing {amount} occurence of »{original}« with »{replacement}«.', 'Replacing {amount} occurrences of »{original}« with »{replacement}«.', number_of_occurrences) self.view.set_message(str_occurrences.format(amount=str(number_of_occurrences), original=original, replacement=replacement)) self.view.set_detail(_('Do you really want to do this?')) self.view.set_buttons([_('_Cancel'), _('_Yes, replace all occurrences')]) self.view.set_cancel_button(0) self.view.set_default_button(1)
def dialog_process_response(self, dialog, result): index = dialog.choose_finish(result) if index == 1: self.search_context.replace_all(self.replacement, -1)

