import sys import gi gi.require_version('Gtk', '4.0') try: gi.require_version('Adw', '1') except ValueError: print("Adwaita library not available, using standard GTK", file=sys.stderr) from gi.repository import Gtk, GLib, Gio
from setzer.app.service_locator import ServiceLocator from setzer.workspace.workspace import Workspace
import time import os
class WorkspaceController(object): ''' Mediator between workspace and view. '''
def __init__(self, workspace): print("Initializing WorkspaceController", file=sys.stderr) self.workspace = workspace self.main_window = ServiceLocator.get_main_window() print(f"Main window in controller: {self.main_window}", file=sys.stderr)
try: self.main_window.headerbar.preview_toggle.connect('toggled', self.on_preview_toggle_toggled) self.main_window.headerbar.help_toggle.connect('toggled', self.on_help_toggle_toggled)
self.main_window.headerbar.document_structure_toggle.connect('toggled', self.on_document_structure_toggle_toggled) self.main_window.headerbar.symbols_toggle.connect('toggled', self.on_symbols_toggle_toggled)
# populate workspace self.workspace.populate_from_disk() open_documents = self.workspace.open_documents if len(open_documents) > 0: self.workspace.set_active_document(open_documents[-1]) except Exception as e: print(f"Error in WorkspaceController initialization: {e}", file=sys.stderr)
def on_preview_toggle_toggled(self, toggle_button, parameter=None): show_preview = toggle_button.get_active() if show_preview: show_help = False else: show_help = self.workspace.show_help self.workspace.set_show_preview_or_help(show_preview, show_help)
if show_preview: self.main_window.headerbar.help_toggle.set_active(False)
def on_help_toggle_toggled(self, toggle_button, parameter=None): show_help = toggle_button.get_active() if show_help: show_preview = False else: show_preview = self.workspace.show_preview self.workspace.set_show_preview_or_help(show_preview, show_help)
if show_help: self.main_window.headerbar.preview_toggle.set_active(False)
def on_document_structure_toggle_toggled(self, toggle_button, parameter=None): show_document_structure = toggle_button.get_active() if show_document_structure: show_symbols = False else: show_symbols = self.workspace.show_symbols self.workspace.set_show_symbols_or_document_structure(show_symbols, show_document_structure)
if show_document_structure: self.main_window.headerbar.symbols_toggle.set_active(False)
def on_symbols_toggle_toggled(self, toggle_button, parameter=None): show_symbols = toggle_button.get_active() if show_symbols: show_document_structure = False else: show_document_structure = self.workspace.show_document_structure self.workspace.set_show_symbols_or_document_structure(show_symbols, show_document_structure)
if show_symbols: self.main_window.headerbar.document_structure_toggle.set_active(False)
class SetzerApplication(Gtk.Application): """Main application class for Setzer"""
def __init__(self): super().__init__(application_id="org.setzer.app", flags=Gio.ApplicationFlags.FLAGS_NONE) self._windows = [] # Keep track of windows to prevent garbage collection
def do_startup(self): Gtk.Application.do_startup(self) print("Application starting up", file=sys.stderr)
def do_activate(self): print("Activating application", file=sys.stderr)
# Initialize application services if hasattr(ServiceLocator, 'init_services') and callable(getattr(ServiceLocator, 'init_services')): print("Initializing services", file=sys.stderr) ServiceLocator.init_services() else: print("Warning: ServiceLocator.init_services() method not found or not callable. " "Application services may not be fully initialized.", file=sys.stderr) # Try to create basic resources try: app_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__))) resources_path = os.path.join(app_dir, 'resources') ServiceLocator.set_resources_path(resources_path) print(f"Set resources path to: {resources_path}", file=sys.stderr) except Exception as e: print(f"Error setting up resources: {e}", file=sys.stderr)
# Get the main window main_window = ServiceLocator.get_main_window() print(f"Main window obtained: {main_window}", file=sys.stderr)
if not main_window: print("Critical Error: ServiceLocator.get_main_window() returned None. UI cannot be initialized.", file=sys.stderr) if hasattr(self, 'quit'): self.quit() sys.exit(1) # Exit if no main window
# Ensure widgets are created for the main window if hasattr(main_window, 'create_widgets') and callable(getattr(main_window, 'create_widgets')): print("Creating widgets", file=sys.stderr) try: main_window.create_widgets() print("Widgets created successfully", file=sys.stderr) except Exception as e: print(f"Error creating widgets: {e}", file=sys.stderr) import traceback traceback.print_exc() else: print("Warning: main_window does not have a callable create_widgets method. UI might be incomplete.", file=sys.stderr)
print("Adding window to application", file=sys.stderr) self.add_window(main_window) self._windows.append(main_window) # Prevent garbage collection
print("Setting window properties", file=sys.stderr) main_window.set_default_size(1200, 800) main_window.set_title("Setzer LaTeX Editor")
print("Presenting window", file=sys.stderr) main_window.present()
# Initialize workspace try: print("Creating workspace", file=sys.stderr) workspace = Workspace() self.controller = WorkspaceController(workspace) self._controller = self.controller # Prevent garbage collection print("Workspace initialized", file=sys.stderr) except Exception as e: print(f"Error initializing workspace: {e}", file=sys.stderr) import traceback traceback.print_exc()
# Set up a timeout to keep the application running def keep_app_alive(): # Keep the application running if main_window.is_visible(): print("Application still running, window visible", file=sys.stderr) else: print("Window not visible, forcing present()", file=sys.stderr) main_window.present() return True # Return True to keep the timeout active
# Add timeout every 2 seconds GLib.timeout_add_seconds(2, keep_app_alive) print("Application activation complete", file=sys.stderr)
if __name__ == "__main__": print("Starting Setzer application", file=sys.stderr) app = SetzerApplication()
# Run the application and enter the GTK main loop print("Running application", file=sys.stderr) exit_status = app.run(sys.argv)
print(f"Application exiting with status {exit_status}", file=sys.stderr) sys.exit(exit_status) ```

